#include <iostream>
using namespace std;

const long long M = 998244353;

long long fastExponentiation(long long base, long long exponent) {
    long long res = 1;
    long long mod = M;
    while (exponent > 0) {
        if (exponent & 1) {
            res = (res * base) % mod;
        }
        base = (base * base) % mod;
        exponent >>= 1;
    }
    return res;
}

long long modularInverse(long long a, long long m) {
    return fastExponentiation(a, m - 2);
}

int main() {
    long long m, n, l, r;
    cin >> m >> n >> l >> r;

    long long total = m * n;
    long long segmentSize = r - l + 1;

    long long result = fastExponentiation(segmentSize, total);
    if (total % 2 == 1) {
        cout << result << "\n";
    } else {
        if (segmentSize % 2 == 0)
            cout << (result * modularInverse(2, M)) % M << "\n";
        else
            cout << (((result + 1) % M) * modularInverse(2, M)) % M << "\n";
    }
    return 0;
}

